using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Core.Contracts;
public enum CastellanReportAction { Report,Resend }
public sealed record CastellanReportInput(EntityId Id,CastellanReportAction Action,EntityId Appointment,string? Original=null);
public sealed record CastellanReportPaper(string Id,EntityId Request,EntityId Appointment,EntityId Sender,EntityId Recipient,EntityId Address,long At,long Revision,CastellanReceipt Observation,string? Original,EntityId? Decision);
public sealed record CastellanReportEntry(CastellanReportInput Input,long At,long Revision,string Paper);
public sealed record CastellanReportState(int Schema,string Policy,CastellanReportEntry[] Entries,CastellanReportPaper[] Papers);
public sealed record CastellanReportView(CastellanReportPaper[] Reports,string[] Retryable);
public static class CastellanReports
{
    public const string Policy="dated-castellan-custody-physical-report-same-observation-retry-v1",Kind="castellan-store-report";
    static void Need([System.Diagnostics.CodeAnalysis.DoesNotReturnIf(false)]bool ok,string s){if(!ok)throw new InvalidDataException(s);}
    static string Hash(string s)=>ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(s));
    static bool Before(CastellanReportPaper p,long at,long rev)=>p.At<at||p.At==at&&p.Revision<rev;
    public static bool OwnIdUsed(ContractWorld w,EntityId id)=>w.CastellanReports?.Entries.Any(e=>e.Input.Id==id)==true||w.CastellanReports?.Papers.Any(p=>p.Request==id)==true;
    static CastellanEntry Appointment(ContractWorld w,EntityId id)=>w.Castellan!.Entries.Single(e=>e.Input.Id==id&&CastleAdministration.IsAppointment(e.Input.Action));
    static CastellanReportPaper Make(ContractWorld w,CastellanReportInput i,long at,long rev){var e=Appointment(w,i.Appointment);Need(!PersonalLife.Resting(w,at,rev)&&Enum.IsDefined(i.Action)&&e.At<=at&&e.Revision<rev&&CommunityStewardship.Local(w,e.Agent,e.Input.Site,at,rev)&&e.Agent==w.PlayerControl,"現地の担当者本人が報告してください");
        CastellanReceipt observation;
        if(i.Action==CastellanReportAction.Report){Need(i.Original==null&&CastleAdministration.Grant(w,e.Input.Site,at,rev)?.Id==i.Appointment,"有効な任命原本がありません");observation=CastleAdministration.Store(w,e.Input.Site,at,rev);}
        else {var old=w.CastellanReports!.Papers.Single(p=>p.Id==i.Original&&p.Appointment==e.Input.Id&&p.Sender==e.Agent);Need(Before(old,at,rev)&&KnownFailure(w,old) is {} failure&&MessageFlow.LearnedAt(w.Messaging,failure.Id,old.Sender.Value)<=at&&w.CastellanReports.Papers.Count(p=>p.Appointment==old.Appointment&&p.Observation==old.Observation&&Before(p,at,rev))<3,"同じ報告の不達を認識してから三通まで再送できます");observation=old.Observation;}
        return new("message:castellan/"+Hash(i.Id.Value),i.Id,e.Input.Id,e.Agent,e.Principal,e.Input.Site,at,rev,observation,i.Original,null);
    }
    static MessageEnvelope Envelope(CastellanReportPaper p)=>new(p.Id,p.Appointment.Value,Kind,p.Sender.Value,p.Recipient.Value,System.Text.Encoding.UTF8.GetString(ContractJson.Write(p)),p.Address.Value,p.At);
    static void Send(ContractWorld w,CastellanReportPaper p){w.CastellanReports=w.CastellanReports! with{Papers=[..w.CastellanReports!.Papers,p]};MessageFlow.Send(w.Messaging,Envelope(p),p.At,1);w.SealedMessages=[..w.SealedMessages,new(p.Id)];}
    static MessageEnvelope? KnownFailure(ContractWorld w,CastellanReportPaper p)=>w.Messaging.Messages.FirstOrDefault(m=>m.Kind=="delivery-failure"&&m.RecipientId==p.Sender.Value&&w.Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id)&&MessageFlow.Knows(w.Messaging,m.Id,p.Sender.Value));
    internal static void Initialize(ContractWorld w){if(CastleAdministration.Enabled(w))w.CastellanReports=new(1,Policy,[],[]);}
    internal static void Apply(ContractWorld w,CastellanReportInput i){var p=Make(w,i,w.ElapsedSeconds,w.CommitSequence);w.CastellanReports=w.CastellanReports! with{Entries=[..w.CastellanReports!.Entries,new(i,w.ElapsedSeconds,w.CommitSequence,p.Id)]};Send(w,p);}
    static EntityId AutoId(ContractWorld w,EntityId decision){string root="request:castellan-auto/"+Hash(decision.Value);var id=new EntityId(root);int n=0;while(FactionStances.OtherIdUsed(w,id,includeCastellanReports:false)||FactionStances.OwnIdUsed(w,id))id=new(root+"/n"+(++n));return id;}
    internal static void Tick(ContractWorld w){if(!CastleAdministration.Enabled(w))return;
        foreach(var d in w.CommunityAdministration!.Decisions.ToArray()){var g=CastleAdministration.Grant(w,d.Site,d.At,d.Revision);if(g==null||g.Agent!=d.Actor||d.Actor==w.PlayerControl||!CommunityStewardship.Local(w,d.Actor,d.Site,d.At,d.Revision)||CommunityStewardship.Authority(w,d.Actor,g.Owner,d.Site,d.At,d.Revision)==null)continue;var id=AutoId(w,d.Id);if(w.CastellanReports!.Papers.Any(p=>p.Request==id))continue;var e=Appointment(w,g.Id);Send(w,new("message:castellan-auto/"+Hash(id.Value),id,g.Id,g.Agent,g.Principal,e.Input.Site,d.At,d.Revision,CastleAdministration.Store(w,d.Site,d.At,d.Revision+1),null,d.Id));}
    }
    public static string? Address(ContractWorld w,MessageEnvelope m)=>w.CastellanReports?.Papers.SingleOrDefault(p=>p.Id==m.Id) is {} p?NewGameWorld.Node(p.Address.Value):null;
    internal static CastellanReportView? View(ContractWorld w){if(!CastleAdministration.Enabled(w))return null;var papers=w.CastellanReports!.Papers;return new(papers.Where(p=>p.Sender==w.PlayerControl||MessageFlow.Knows(w.Messaging,p.Id,w.PlayerControl.Value)).ToArray(),papers.Where(p=>p.Sender==w.PlayerControl&&KnownFailure(w,p)!=null&&papers.Count(q=>q.Appointment==p.Appointment&&q.Observation==p.Observation)<3).Select(p=>p.Id).ToArray());}
    internal static void Validate(ContractWorld w){if(!CastleAdministration.Enabled(w)){Need(w.CastellanReports==null,"旧版へ城主報告を追加できません");return;}Need(w.CastellanReports is {Schema:1,Policy:Policy,Entries:not null,Papers:not null},"城主報告の原本がありません");var s=w.CastellanReports;long rev=0,at=0;var ids=new HashSet<EntityId>();foreach(var e in s.Entries){Need(e.At>=at&&e.At<=w.ElapsedSeconds&&e.Revision>rev&&e.Revision<=w.CommitSequence&&ids.Add(e.Input.Id)&&!FactionStances.OtherIdUsed(w,e.Input.Id,includeCastellanReports:false)&&!FactionStances.OwnIdUsed(w,e.Input.Id),"報告入力の順序・IDが不正です");Need(s.Papers.Single(p=>p.Id==e.Paper)==Make(w,e.Input,e.At,e.Revision),"報告原本と当時の観測が違います");at=e.At;rev=e.Revision;}
        foreach(var d in w.CommunityAdministration!.Decisions){var g=CastleAdministration.Grant(w,d.Site,d.At,d.Revision);if(g!=null&&g.Agent==d.Actor&&d.Actor!=w.PlayerControl&&CommunityStewardship.Local(w,d.Actor,d.Site,d.At,d.Revision)&&CommunityStewardship.Authority(w,d.Actor,g.Owner,d.Site,d.At,d.Revision)!=null)Need(s.Papers.Count(p=>p.Decision==d.Id)==1,"現地NPC判断の報告原本が欠落しています");}
        Need(s.Papers.Select(p=>p.Id).Distinct().Count()==s.Papers.Length,"報告が重複しています");foreach(var p in s.Papers){Need(p.At<=w.ElapsedSeconds&&p.Revision<=w.CommitSequence&&w.Messaging.Messages.Contains(Envelope(p))&&w.SealedMessages.Contains(new(p.Id)),"封書の配送原本がありません");if(p.Decision is {} decision){var d=w.CommunityAdministration!.Decisions.Single(d=>d.Id==decision);var g=CastleAdministration.Grant(w,d.Site,d.At,d.Revision);Need(g!=null&&g.Agent==d.Actor&&d.Actor!=w.PlayerControl&&CommunityStewardship.Local(w,d.Actor,d.Site,d.At,d.Revision)&&CommunityStewardship.Authority(w,d.Actor,g.Owner,d.Site,d.At,d.Revision)!=null&&p.Appointment==g.Id&&p.Sender==g.Agent&&p.Recipient==g.Principal&&p.Address==g.Site&&p.At==d.At&&p.Revision==d.Revision&&p.Original==null&&p.Request==AutoId(w,d.Id)&&p.Id=="message:castellan-auto/"+Hash(p.Request.Value)&&p.Observation==CastleAdministration.Store(w,d.Site,d.At,d.Revision+1),"NPC報告の現地判断と観測が違います");}else Need(s.Entries.Count(e=>e.Paper==p.Id)==1,"報告に本人の発送操作がありません");}
    }
}
public sealed partial class WorldSession
{
    public CastellanReportView? CastellanReportsView(){lock(gate)return CastellanReports.View(state);}
    public CommandResult SendCastellanReport(CastellanReportInput i,EntityId actor,long revision){lock(gate){if(actor!=state.PlayerControl||!CastleAdministration.Enabled(state))return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,"担当者本人の報告ではありません");var old=state.CastellanReports!.Entries.SingleOrDefault(e=>e.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"発送済みです");if(FactionStances.OtherIdUsed(state,i.Id)||FactionStances.OwnIdUsed(state,i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"使用済みIDです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");try{Change(w=>CastellanReports.Apply(w,i));return new(ResultCode.Accepted,i.Id,state.CommitSequence,"時点付きの封書を発送しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
